class Remote:
 def __init__(self,c,host,port=8080,tls=False):
  self.p=subprocess.Popen(['docker','exec','-i',c,'python3','-u','-c',remote_program,host,str(port),'yes' if tls else 'no'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
  line=self.p.stdout.readline()
