 def exchange(self,value):
  self.p.stdin.write(json.dumps(value)+'\n');self.p.stdin.flush();return json.loads(self.p.stdout.readline())['ok']
 def receive(self,value):return self.exchange('receive:'+value)
 def close(self):
  self.p.stdin.close();self.p.wait(timeout=5)
