  self.s=socket.create_connection((host,8080),3);self.s.settimeout(1.5);assert self.s.recv(64).startswith(b'peer-');sessions.append(self)
 def exchange(self,value):
  try:self.s.sendall(value.encode());return self.s.recv(4096)==value.encode()
  except (OSError,TimeoutError):return False
 def receive(self,value):
  try:return self.s.recv(4096)==value.encode()
  except (OSError,TimeoutError):return False
 def close(self):self.s.close()
class Callback(socketserver.BaseRequestHandler):
 def handle(self):
  self.request.recv(4096);self.request.sendall(b'HTTP/1.1 200 OK\r\nContent-Length: 11\r\nConnection: close\r\n\r\ncallback-ok')
class Echo(socketserver.BaseRequestHandler):
 def handle(self):
  self.request.sendall(b'peer-host\n')
  while data:=self.request.recv(4096):self.request.sendall(data)
socketserver.ThreadingTCPServer.allow_reuse_address=True
